function fillVenues(query=''){const filtered=rooms.filter(r=>(r.name+r.region+r.format).toLowerCase().includes(query.toLowerCase()));$('#venue').replaceChildren(...filtered.map(r=>new Option(r.name,r.id)));if(room&&filtered.some(r=>r.id===room.id))$('#venue').value=room.id;$('#venue').disabled=!filtered.length;if(room&&filtered.length&&!filtered.some(r=>r.id===room.id))loadRoom(filtered[0].id);$('#venue-meta').textContent=filtered.length?`${filtered.length}개 선정 상영관 · 전체 영화관 목록이 아닙니다`:'검색 결과가 없습니다';}
