function setMode(mode){cinema?.setMode(mode);$$('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',b.dataset.mode===mode);});$('.walk-controls').hidden=!!cinema&&mode!=='walk';}
function sit(){cinema?.sit(row,seat);setMode('seat');if(innerWidth<721)$('#app').classList.remove('panel-visible');}
function resetCalibration(apply=true){for(const[id,v]of [['front',10],['pitch',1.3],['rise',.35]]){$('#'+id).value=v;$('#'+id+'-value').textContent=v+(id==='fov'?'°':' m');}if(apply)calibrate();}
