$('#venue').onchange=e=>loadRoom(e.target.value);$('#search').oninput=e=>fillVenues(e.target.value);$('#row').onchange=e=>{row=+e.target.value;updateSeat();};$('#seat').onchange=e=>{seat=+e.target.value;updateSeat();};$('#sit').onclick=sit;$$('[data-mode]').forEach(b=>b.onclick=()=>b.dataset.mode==='seat'?sit():setMode(b.dataset.mode));['front','pitch','rise'].forEach(id=>$('#'+id).oninput=calibrate);$('#reset-model').onclick=()=>resetCalibration();$('#panel-open').onclick=()=>$('#app').classList.add('panel-visible');$('#collapse').onclick=()=>$('#app').classList.remove('panel-visible');
function parseVideo(value){const raw=value.trim();if(/^[\w-]{11}$/.test(raw))return raw;try{const u=new URL(raw);if(u.hostname==='youtu.be')return /^[\w-]{11}$/.test(u.pathname.slice(1))?u.pathname.slice(1):null;if(['youtube.com','www.youtube.com','m.youtube.com','www.youtube-nocookie.com'].includes(u.hostname)){const id=u.searchParams.get('v')||u.pathname.split('/')[2];return /^[\w-]{11}$/.test(id||'')?id:null;}}catch{}return null;}
function loadAPI(){if(window.YT?.Player)return Promise.resolve();if(apiPromise)return apiPromise;apiPromise=new Promise((resolve,reject)=>{window.onYouTubeIframeAPIReady=resolve;const script=document.createElement('script');script.src='https://www.youtube.com/iframe_api';script.onerror=()=>{apiPromise=null;reject(new Error('API load failed'));};document.head.append(script);setTimeout(()=>{if(!window.YT?.Player){apiPromise=null;reject(new Error('API timed out'));}},15000);});return apiPromise;}
function status(text){$('#video-status').textContent=text;}
async function openVideo(value){const request=++videoRequest;const id=parseVideo(value);if(!id){status('올바른 YouTube 주소 또는 11자리 영상 ID를 입력해 주세요');$('#video-url').setAttribute('aria-invalid','true');return;}$('#video-url').removeAttribute('aria-invalid');$('#youtube-link').href=`https://www.youtube.com/watch?v=${id}`;$('#youtube-link').hidden=false;$('#close-video').hidden=false;status('YouTube 플레이어를 불러오는 중…');clearTimeout(videoTimeout);try{await loadAPI();if(request!==videoRequest)return;$('#screen-player').hidden=false;$('#fallback-comparison').hidden=true;updateVideoFit();$('#stage-framing-note').textContent='YouTube 원본 비율 유지 · 화면비를 바꿔도 없는 장면은 복원되지 않습니다';pendingVideo=id;if(player){if(playerReady)player.cueVideoById(id);}else{player=new YT.Player('youtube-player',{host:'https://www.youtube-nocookie.com',videoId:id,width:1280,height:720,playerVars:{playsinline:1,controls:1,rel:0,origin:location.origin},events:{onReady:()=>{playerReady=true;if($('#screen-player').hidden){player.stopVideo();return;}if(pendingVideo&&pendingVideo!==id)player.cueVideoById(pendingVideo);status('스크린의 재생 버튼을 눌러 주세요 · 소리는 YouTube에서 조절합니다');},onStateChange:e=>{if($('#screen-player').hidden)return;if(e.data===YT.PlayerState.PLAYING){clearTimeout(videoTimeout);status('재생 중 · 공식 YouTube 플레이어');}else if(e.data===YT.PlayerState.PAUSED)status('일시 정지');else if(e.data===YT.PlayerState.ENDED)status('영상이 끝났습니다');else if(e.data===YT.PlayerState.CUED)status('스크린의 재생 버튼을 눌러 주세요');},onError:e=>{if($('#screen-player').hidden)return;clearTimeout(videoTimeout);const reason=({2:'유효하지 않은 영상',5:'HTML5 재생 오류',100:'삭제되었거나 비공개인 영상',101:'제작자가 퍼가기를 허용하지 않은 영상',150:'제작자가 퍼가기를 허용하지 않은 영상',153:'YouTube 재생 환경 인증 오류'})[e.data]||'재생 제한';status(`${reason} · YouTube에서 열기를 이용해 주세요`);}}});}videoTimeout=setTimeout(()=>status('재생되지 않으면 영상의 로그인·연령·퍼가기 제한을 확인하거나 YouTube에서 열어 주세요'),25000);}catch{if(request!==videoRequest)return;status('이 환경에서 YouTube를 불러오지 못했습니다 · YouTube에서 열기를 이용해 주세요');}}
$('#video-form').onsubmit=e=>{e.preventDefault();openVideo($('#video-url').value);};$('#sample-video').onclick=()=>{$('#video-url').value='https://www.youtube.com/watch?v='+$('#sample-select').value;openVideo($('#video-url').value);};$('#close-video').onclick=()=>{videoRequest++;pendingVideo=null;if(playerReady)player?.stopVideo();$('#screen-player').hidden=true;$('#fallback-comparison').hidden=!$('#stage').classList.contains('no-webgl');$('#stage-framing-note').textContent='설명용 1.43 원본 · 같은 좌석과 카메라 유지';$('#close-video').hidden=true;clearTimeout(videoTimeout);status('영상이 닫혔습니다 · 새 YouTube 주소를 입력할 수 있습니다');};

framing=createFraming($('#framing-content'),{onTexture:applyScreenContent});framing.setScreen(config.screenWidth,config.screenHeight);$('#open-framing').onclick=()=>$('#framing-dialog').showModal();$('#close-framing').onclick=()=>$('#framing-dialog').close();$('#framing-dialog').addEventListener('click',e=>{if(e.target===$('#framing-dialog'))$('#framing-dialog').close();});

// A captured analog pointer controls movement; a second canvas pointer controls looking.
const stick=$('#move-stick'),knob=$('#stick-knob');let stickPointer=null,stickVector={x:0,z:0},stickRAF=0,stickTime=0;const stickKeys=new Set();
function setStick(x,z,visualX=0,visualY=0){stickVector={x,z};stick.dataset.vectorX=x.toFixed(4);stick.dataset.vectorZ=z.toFixed(4);stick.dataset.active=String(Math.hypot(x,z)>0);knob.style.transform=`translate(${visualX}px,${visualY}px)`;const mag=Math.hypot(x,z);if(mag>Number(stick.dataset.peakMagnitude||0)){stick.dataset.peakMagnitude=mag.toFixed(4);stick.dataset.peakX=x.toFixed(4);stick.dataset.peakZ=z.toFixed(4);}$('#movement-feedback').textContent=mag>0?(cinema?'끌어당긴 방향으로 이동 중':'입력 확인 · 이 브라우저는 3D 이동 불가'):'놓으면 정지 · 시선은 화면 드래그';if(mag&&!stickRAF){stickTime=performance.now();stickRAF=requestAnimationFrame(moveStick);}}
function moveStick(t){const dt=Math.min(.05,(t-stickTime)/1000||0);stickTime=t;cinema?.move(stickVector.x*dt*2.3,stickVector.z*dt*2.3);if(Math.hypot(stickVector.x,stickVector.z)>0)stickRAF=requestAnimationFrame(moveStick);else stickRAF=0;}
function resetStick(){stickPointer=null;stickKeys.clear();setStick(0,0);if(stickRAF)cancelAnimationFrame(stickRAF);stickRAF=0;}
function updateStickPointer(e){const r=stick.getBoundingClientRect(),radius=Math.max(20,(r.width-knob.offsetWidth)/2-6);const dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,len=Math.hypot(dx,dy),normal=Math.min(1,len/radius),magnitude=normal<=.14?0:(normal-.14)/.86;const unitX=len?dx/len:0,unitY=len?dy/len:0;setStick(unitX*magnitude,-unitY*magnitude,unitX*Math.min(len,radius),unitY*Math.min(len,radius));}
stick.addEventListener('pointerdown',e=>{if(stickPointer!==null)return;e.preventDefault();e.stopPropagation();stickPointer=e.pointerId;stick.dataset.peakMagnitude='0';stick.dataset.peakX='0';stick.dataset.peakZ='0';stick.setPointerCapture(e.pointerId);updateStickPointer(e);});stick.addEventListener('pointermove',e=>{if(e.pointerId!==stickPointer)return;e.preventDefault();e.stopPropagation();updateStickPointer(e);});for(const type of ['pointerup','pointercancel','lostpointercapture'])stick.addEventListener(type,e=>{if(e.pointerId!==stickPointer)return;e.stopPropagation();resetStick();});
function keyboardStick(){const x=Number(stickKeys.has('d')||stickKeys.has('arrowright'))-Number(stickKeys.has('a')||stickKeys.has('arrowleft'));const z=Number(stickKeys.has('w')||stickKeys.has('arrowup'))-Number(stickKeys.has('s')||stickKeys.has('arrowdown'));const length=Math.max(1,Math.hypot(x,z));setStick(x/length,z/length,x/length*30,-z/length*30);}
stick.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if(!['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright'].includes(key))return;e.preventDefault();e.stopPropagation();stickKeys.add(key);keyboardStick();});stick.addEventListener('keyup',e=>{e.preventDefault();e.stopPropagation();stickKeys.delete(e.key.toLowerCase());keyboardStick();});stick.addEventListener('blur',resetStick);window.addEventListener('blur',resetStick);document.addEventListener('visibilitychange',()=>{if(document.hidden)resetStick();});setStick(0,0);
function updateVideoFit(){if(!config)return;const screenRatio=config.screenWidth/config.screenHeight;if($('#stage').classList.contains('no-webgl')){for(const el of [$('#screen-player'),$('#fallback-comparison')]){el.style.width=`min(80%,${screenRatio*38}vh)`;el.style.left='50%';el.style.transform='translateX(-50%)';el.style.aspectRatio=String(screenRatio);el.style.maxHeight='none';}}const w=activeRatio>screenRatio?100:100*activeRatio/screenRatio;const h=activeRatio>screenRatio?100*screenRatio/activeRatio:100;Object.assign($('#video-frame').style,{width:w+'%',height:h+'%',left:(100-w)/2+'%',top:(100-h)/2+'%'});}
function applyScreenContent(url,meta){activeRatio=meta.ratio;$$('[data-stage-ratio]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.stageRatio===activeRatio)));updateVideoFit();const request=++textureRequest;const img=new Image();img.onload=()=>{if(request!==textureRequest||!config)return;const canvas=document.createElement('canvas');canvas.width=1800;canvas.height=Math.round(1800*config.screenHeight/config.screenWidth);const ctx=canvas.getContext('2d');ctx.fillStyle='#000';ctx.fillRect(0,0,canvas.width,canvas.height);const scale=Math.min(canvas.width/img.width,canvas.height/img.height);const w=img.width*scale,h=img.height*scale;ctx.drawImage(img,(canvas.width-w)/2,(canvas.height-h)/2,w,h);const fitted=canvas.toDataURL('image/png');cinema?.setScreenImage(fitted);$('#fallback-comparison').src=fitted;$('#fallback-comparison').style.aspectRatio=String(config.screenWidth/config.screenHeight);$('#fallback-comparison').hidden=!$('#stage').classList.contains('no-webgl')||!$('#screen-player').hidden;};img.src=url;}
$$('[data-stage-ratio]').forEach(b=>b.onclick=()=>framing.setRatio(+b.dataset.stageRatio));$('#show-comparison').onclick=()=>{videoRequest++;if(playerReady)player.stopVideo();$('#screen-player').hidden=true;$('#close-video').hidden=true;clearTimeout(videoTimeout);$('#fallback-comparison').hidden=!$('#stage').classList.contains('no-webgl');$('#stage-framing-note').textContent='설명용 1.43 원본 · 같은 좌석과 카메라 유지';status('직접 만든 비교 장면입니다 · 실제 영화 장면이 아닙니다');};
